bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
const {Pool}=pg;
const env=process.env;
const user=env.VIDEOBOT_DB_USER,host=env.VIDEOBOT_DB_HOST;
const password=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const pool=new Pool({host,user,password,database:'videobot',port:5432,max:1,connectionTimeoutMillis:4000});
try{
 const p=await pool.query("SELECT p.pack_name, COUNT(i.file_id)::int AS db_count FROM videobot_sticker_packs p LEFT JOIN videobot_sticker_items i ON i.pack_name=p.pack_name WHERE p.status='active' GROUP BY p.pack_name ORDER BY p.pack_name LIMIT 100");
 const q=await pool.query("SELECT phase,COUNT(*)::int AS n FROM videobot_sticker_registration_receipts WHERE phase <> 'registered' GROUP BY phase");
 let apiOk=0,apiFail=0,mismatch=0,withFive=0,largest=0,dbLargest=0;
 for(const row of p.rows){
  dbLargest=Math.max(dbLargest,row.db_count);
  try{
   const result=await fetch('https://api.telegram.org/bot'+token+'/getStickerSet',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:row.pack_name}),signal:AbortSignal.timeout(6000)});
   const data=await result.json();
   if(!data.ok||!Array.isArray(data.result?.stickers)){apiFail++;continue;}
   apiOk++;
   const count=data.result.stickers.length;
   largest=Math.max(largest,count);
   if(count>=5)withFive++;
   if(count!==row.db_count)mismatch++;
  }catch{apiFail++;}
 }
 const pending=Object.fromEntries(q.rows.map(v=>[v.phase,v.n]));
 console.log('STICKER_INVENTORY_READBACK=PASS');
 console.log('PACK_ROWS='+p.rowCount);
 console.log('TELEGRAM_PACK_READ_SUCCESS='+apiOk);
 console.log('TELEGRAM_PACK_READ_FAILED='+apiFail);
 console.log('MAX_TELEGRAM_PACK_ITEMS='+largest);
 console.log('MAX_DB_PACK_ITEMS='+dbLargest);
 console.log('PACKS_AT_LEAST_FIVE='+withFive);
 console.log('PACK_COUNT_MISMATCH='+mismatch);
 console.log('REGISTRATION_PENDING='+JSON.stringify(pending));
 const r=await fetch('http://127.0.0.1:8766/shop',{signal:AbortSignal.timeout(4000)});
 console.log('SHOP_HTML_STATUS='+r.status);
 console.log('SHOP_FRAME_HEADER='+(r.headers.has('x-frame-options')?'BLOCKING':'CSP_ONLY'));
 console.log('SHOP_CSP_TELEGRAM='+(r.headers.get('content-security-policy')?.includes('frame-ancestors https://web.telegram.org')?'YES':'NO'));
 const publicUrl=env.VIDEOBOT_SHOP_PUBLIC_URL??'';
 console.log('SHOP_PUBLIC_URL_CONFIGURED='+(publicUrl==='https://shop.hentaigay.org/'||publicUrl==='https://shop.hentaigay.org'?'YES':publicUrl===''?'NO':'OTHER'));
}catch{console.log('STICKER_INVENTORY_READBACK=FAILED');process.exitCode=1;}
finally{await pool.end();}
NODE
